<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watchEffect } from 'vue'
import { useRouter } from 'vue-router'
import { useSettingsStore } from '../stores/settings.store'
import { useWeatherStore } from '../stores/weather.store'
import { useCalendarStore } from '../stores/calendar.store'
import { useTimerStore } from '../stores/timer.store'
import { useUiStore } from '../stores/ui.store'
import { solarTimes,moonPhase } from '../services/astronomy'
import IstanteIcon from './IstanteIcon.vue'
const settings=useSettingsStore(),weather=useWeatherStore(),cal=useCalendarStore(),timer=useTimerStore(),ui=useUiStore(),router=useRouter();const now=ref(new Date());let tick=0;onMounted(()=>tick=window.setInterval(()=>now.value=new Date(),30000));onBeforeUnmount(()=>clearInterval(tick))
let weatherKey='';watchEffect(()=>{if(settings.data.weatherEnabled&&settings.data.latitude!=null&&settings.data.longitude!=null){const key=`${settings.data.latitude.toFixed(3)},${settings.data.longitude.toFixed(3)}`;if(key!==weatherKey){weatherKey=key;void weather.load(settings.data.latitude,settings.data.longitude)}}})
const target=computed(()=>new Date(now.value.getFullYear()+1,0,1,0,0,0));const yearProgress=computed(()=>{const a=new Date(now.value.getFullYear(),0,1),b=target.value;return Math.max(0,Math.min(100,((+now.value-+a)/(+b-+a))*100))});
const remaining=computed(()=>{const from=new Date(now.value),to=target.value;let months=(to.getFullYear()-from.getFullYear())*12+to.getMonth()-from.getMonth();const anchor=new Date(from);anchor.setMonth(anchor.getMonth()+months);if(+anchor>+to){months--;anchor.setMonth(anchor.getMonth()-1)}const ms=Math.max(0,+to-+anchor),days=Math.floor(ms/86400000),hours=Math.floor((ms%86400000)/3600000),minutes=Math.floor((ms%3600000)/60000);if(months>0)return[{v:String(months).padStart(2,'0'),u:months===1?'mese':'mesi'},{v:String(days).padStart(2,'0'),u:days===1?'giorno':'giorni'},{v:String(hours).padStart(2,'0'),u:hours===1?'ora':'ore'}];const totalDays=Math.floor((+to-+from)/86400000);return[{v:String(totalDays).padStart(2,'0'),u:totalDays===1?'giorno':'giorni'},{v:String(hours).padStart(2,'0'),u:hours===1?'ora':'ore'},{v:String(minutes).padStart(2,'0'),u:minutes===1?'minuto':'minuti'}]})
const upcoming=computed(()=>cal.sortedEvents.find(e=>+new Date(e.end||e.start)>=+now.value));const astro=computed(()=>{const lat=settings.data.latitude??44.49,lon=settings.data.longitude??11.34;const t=solarTimes(now.value,lat,lon),phase=moonPhase(now.value);return{rise:t.sunrise.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}),set:t.sunset.toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}),phase}});const moonName=computed(()=>astro.value.phase<.08||astro.value.phase>.92?'Luna nuova':astro.value.phase<.42?'Luna crescente':astro.value.phase<.58?'Luna piena':'Luna calante');const targetLabel=computed(()=>target.value.toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}).replace(/^./,m=>m.toLowerCase())+' · 00:00');const upcomingWhen=computed(()=>upcoming.value?new Date(upcoming.value.start).toLocaleString('it-IT',{weekday:'short',hour:'2-digit',minute:'2-digit'}):'')
function timerToggle(){if(timer.status==='running')timer.pause();else if(timer.status==='paused')timer.resume();else ui.timerOpen=true}
</script>
<template><section class="dashboard-lower chrome"><div class="active-info-strip"><button v-if="settings.data.weatherEnabled" class="environment-line" type="button"><span class="weather-line"><IstanteIcon name="cloud" :size="15"/><strong v-if="weather.temperature!=null">{{Math.round(weather.temperature)}}°</strong><span v-if="weather.condition">{{weather.condition}}</span></span><span class="info-divider"/><span class="solar-time"><IstanteIcon name="sun" :size="14"/><span>Alba</span><time>{{astro.rise}}</time></span><span class="solar-time"><IstanteIcon name="moon" :size="14"/><span>Tramonto</span><time>{{astro.set}}</time></span><span class="moon-caption">{{moonName}}</span></button><button v-if="upcoming" class="upcoming-event" type="button" @click="router.push('/calendar')"><IstanteIcon name="calendar" :size="15"/><span class="upcoming-details"><small>Adesso</small><b>{{upcoming.title}}</b></span><time>{{upcomingWhen}}</time><IstanteIcon name="arrow" :size="14"/></button><section v-if="timer.status!=='idle'" class="timer-chip"><button class="timer-chip-main" @click="ui.timerOpen=true"><IstanteIcon name="clock" :size="16"/><span>Un tempo per te</span><strong>{{timer.formatted}}</strong></button><button class="timer-chip-action" :aria-label="timer.status==='running'?'Metti in pausa il timer':'Riprendi il timer'" @click="timerToggle"><IstanteIcon :name="timer.status==='running'?'pause':'play'" :size="15"/></button><button class="timer-chip-action" aria-label="Elimina timer" @click="timer.reset()"><IstanteIcon name="trash" :size="15"/></button></section></div><section class="goal-strip"><div class="goal-heading"><span class="section-label">Il prossimo capitolo</span><h2>Verso il {{target.getFullYear()}}</h2></div><div class="countdown"><template v-for="(part,i) in remaining" :key="part.u"><span v-if="i" class="count-separator">/</span><div><strong>{{part.v}}</strong><span>{{part.u}}</span></div></template></div><div class="goal-progress"><div class="progress-labels"><span>Il percorso di quest'anno</span><span>{{yearProgress.toFixed(1).replace('.',',')}}%</span></div><div class="progress-track"><i :style="{width:`${yearProgress}%`}"/></div><p class="goal-date">{{targetLabel}}</p></div></section></section></template>
<style scoped>
.dashboard-lower{width:100%;min-width:0}.active-info-strip{min-height:82px;display:grid;justify-items:center;align-content:end;gap:9px;margin-bottom:15px}.environment-line{display:flex;align-items:center;justify-content:center;gap:13px;border:0;background:transparent;color:var(--muted);font:400 10px/1.2 var(--sans);padding:4px 8px}.weather-line,.solar-time{display:flex;align-items:center;gap:6px;white-space:nowrap}.weather-line strong{font-weight:500;color:var(--ink)}.environment-line :deep(svg){color:var(--accent)}.info-divider{width:1px;height:18px;background:var(--line)}.moon-caption{color:var(--faint);white-space:nowrap}.upcoming-event{display:flex;align-items:center;gap:9px;max-width:430px;min-height:42px;padding:6px 11px;border:1px solid var(--line);border-radius:11px;background:color-mix(in srgb,var(--accent-soft) 58%,transparent);color:var(--ink);text-align:left}.upcoming-event>svg{color:var(--accent)}.upcoming-details{display:grid;min-width:0}.upcoming-details small{font-size:8px;color:var(--muted)}.upcoming-details b{font:500 10px/1.25 var(--sans);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:250px}.upcoming-event time{margin-left:auto;color:var(--muted);font-size:8px;white-space:nowrap}.timer-chip{display:flex;align-items:center;min-height:38px;border:1px solid var(--line);border-radius:999px;background:color-mix(in srgb,var(--surface) 88%,transparent);box-shadow:0 8px 28px rgba(0,0,0,.04);padding:2px 4px 2px 11px}.timer-chip-main{display:flex;align-items:center;gap:9px;border:0;background:transparent;color:var(--muted);font-size:11px;padding:5px 7px 5px 0}.timer-chip-main :deep(svg){color:var(--accent)}.timer-chip-main strong{font:400 15px/1 var(--sans);color:var(--ink);font-variant-numeric:tabular-nums}.timer-chip-action{width:31px;height:31px;border:0;border-radius:50%;display:grid;place-items:center;background:transparent;color:var(--muted)}.timer-chip-action:hover{background:var(--accent-soft);color:var(--ink)}.goal-strip{border-top:1px solid var(--line);border-bottom:1px solid var(--line);min-height:138px;padding:25px 0 22px;display:grid;grid-template-columns:1fr auto 1fr;gap:clamp(35px,8vw,105px);align-items:center}.section-label{display:block;text-transform:uppercase;letter-spacing:.15em;font-weight:500;font-size:9px;color:var(--muted);margin-bottom:9px}.goal-heading h2{margin:0;font:400 19px/1.35 var(--sans);letter-spacing:-.035em}.countdown{display:flex;gap:22px;align-items:center}.countdown>div{text-align:center;display:flex;flex-direction:column;gap:6px;min-width:42px}.countdown strong{font:300 28px/1 var(--sans);letter-spacing:-.035em;font-variant-numeric:tabular-nums}.countdown>div>span{font:400 9px/1.1 var(--sans);letter-spacing:.08em;color:var(--muted)}.count-separator{font:200 20px/1 var(--sans);color:var(--faint);opacity:.5;margin-top:-15px}.goal-progress{width:100%;max-width:282px;justify-self:end}.progress-labels{display:flex;justify-content:space-between;gap:12px;font-size:10px;color:var(--muted)}.progress-labels span:last-child{color:var(--accent);font-variant-numeric:tabular-nums}.progress-track{height:2px;background:var(--line);margin-top:11px;overflow:hidden;border-radius:4px}.progress-track i{display:block;height:100%;background:var(--accent);transition:width 1s}.goal-date{color:var(--faint);font-size:9px;margin:9px 0 0;text-align:right}@media(max-width:900px){.goal-strip{gap:24px}.moon-caption{display:none}.goal-progress{max-width:230px}.countdown{gap:14px}}@media(max-width:740px){.active-info-strip{min-height:58px;gap:7px;margin-bottom:9px}.environment-line{gap:7px;font-size:8.5px;max-width:100%;overflow:hidden}.environment-line .weather-line span:last-child,.info-divider{display:none}.upcoming-event{max-width:min(360px,94vw)}.timer-chip{max-width:94vw}.goal-strip{min-height:0;padding:14px 0 12px;grid-template-columns:1fr;gap:12px;text-align:center}.goal-heading .section-label{margin-bottom:4px}.goal-heading h2{font-size:16px}.countdown{justify-content:center;gap:12px}.countdown strong{font-size:21px}.goal-progress{width:min(86%,340px);max-width:none;justify-self:center}.goal-date{text-align:center;font-size:8px}.progress-labels{font-size:8.5px}}@media(max-width:740px) and (orientation:landscape){.active-info-strip{display:flex;justify-content:center;align-items:center;min-height:38px;margin-bottom:5px}.upcoming-event{display:none}.timer-chip{min-height:32px}.environment-line{padding:2px 6px}.goal-strip{grid-template-columns:1fr auto 1fr;gap:18px;padding:8px 0;min-height:70px;text-align:left}.goal-heading h2{font-size:14px}.goal-heading .section-label{font-size:7px}.countdown strong{font-size:17px}.countdown>div>span{font-size:7px}.goal-progress{width:100%;max-width:220px;justify-self:end}.goal-date{text-align:right}.progress-labels{font-size:7.5px}}
</style>
